// Geometry import (OBJ, STL, GLB), mesh measures, convex hulls and decomposition (box3d-webgpu-kit/geometry).
// Files are generated by the same fixture writers the test uses (packages/box3d-kit/test/fixtures/geometry-models.mjs).
import {kit, memo, defineCases, relative, absolute, order} from '../lib.mjs';
import {boxModel, sphereModel, prismModel, modelMesh, objText, asciiSTL, binarySTL, glbOf} from '../../packages/box3d-kit/test/fixtures/geometry-models.mjs';

const G = 9.81, HZ = 240, SUB = 4;
const FILE = 'packages/box3d-kit/test/v10-geometry.test.mjs';
const T = {
  cube: 'one unit cube as OBJ, ASCII STL, binary STL and GLB: volume 1, the same bounds, closed and convex',
  tetra: 'a tetrahedron has volume abc/6 and centroid (a, b, c)/4; transforms scale, move and mirror it correctly',
  sphere: 'a UV sphere converges to 4/3 pi r^3 at second order in the resolution',
  hull: 'convex hulls: exact for a cube, inscribed and close for a decimated sphere',
  decompose: 'convex decomposition: polyhedral solids split exactly, a torus is approached as hulls are added',
  mass: 'a hull body from an imported cube has mass = density x volume, in every format',
  ramp: 'an imported ramp mesh: a sphere slides down it at g sin(theta), and its sampled height field matches',
  welded: 'an L-shaped mesh becomes welded hulls with the right mass that rest on the ground',
};
const geometry = () => kit('geometry');
const si = async (extra = {}) => (await kit('index')).createWorld({step: 1 / HZ, subSteps: SUB, gravity: [0, -G, 0], ...extra});
const run = (world, seconds) => { for (let i = 0; i < Math.round(seconds * HZ); i++) world.step(); };

const cubeVolume = format => async () => {
  const {parseOBJ, parseSTL, parseGLB, meshVolume} = await geometry(), cube = boxModel(), reference = modelMesh(cube);
  const mesh = {obj: () => parseOBJ(objText(cube))[0], 'ascii-stl': () => parseSTL(asciiSTL(reference)), 'binary-stl': () => parseSTL(binarySTL(reference)), glb: () => parseGLB(glbOf(reference))[0]}[format]();
  return meshVolume(mesh);
};

const tetra = () => memo('geometry/tetra', async () => {
  const {meshVolume, meshCenterOfMass, transformMesh} = await geometry(), a = 1.5, b = 2, c = 3;
  const mesh = {vertices: new Float32Array([0, 0, 0, a, 0, 0, 0, b, 0, 0, 0, c]), indices: new Uint32Array([0, 2, 1, 0, 1, 3, 0, 3, 2, 1, 2, 3])};
  const centre = meshCenterOfMass(mesh);
  return {volume: meshVolume(mesh), centroidError: Math.max(Math.abs(centre[0] - a / 4), Math.abs(centre[1] - b / 4), Math.abs(centre[2] - c / 4)),
    scaled: meshVolume(transformMesh(mesh, {scale: [2, 3, 4], rotation: [0, 0, Math.SQRT1_2, Math.SQRT1_2], position: [10, 20, 30]}))};
});

const SPHERE_R = 0.75, SPHERE_V = 4 / 3 * Math.PI * SPHERE_R ** 3;
const sphereVolume = rings => memo(`geometry/sphere/${rings}`, async () => {
  const {parseOBJ, meshVolume} = await geometry();
  return meshVolume(parseOBJ(objText(sphereModel(SPHERE_R, rings)))[0]);
});

const hullCases = () => memo('geometry/hulls', async () => {
  const {convexHull, toHullShape, meshVolume} = await geometry();
  const points = [...modelMesh(boxModel()).vertices, 0.5, 0.5, 0.5, 0.2, 0.9, 0.1, 0.5, 0.5, 1, 0, 0.3, 0.3, 1, 1, 0.5];
  const sides = 32, prism = modelMesh(prismModel(Array.from({length: sides}, (_, k) => [Math.cos(2 * Math.PI * k / sides), Math.sin(2 * Math.PI * k / sides)]), -1, 1));
  const sphere = modelMesh(sphereModel(0.5, 32));
  return {cube: meshVolume(convexHull(points)), prism: meshVolume(convexHull(toHullShape(prism, {maxPoints: 64}).points)),
    sphereHull: meshVolume(convexHull(sphere)), sphereMesh: meshVolume(sphere)};
});

const lShape = () => memo('geometry/l-shape', async () => {
  const {parseOBJ, transformMesh, meshVolume, convexDecompose, createBodiesFromMesh} = await geometry();
  const model = prismModel([[0, 0], [2, 0], [2, 1], [1, 1], [1, 2], [0, 2]], 0, 1, 3);
  const unit = modelMesh(model), split = convexDecompose(unit);
  const mesh = transformMesh(parseOBJ(objText(model))[0], {scale: 0.5}), density = 600, drop = 0.2;
  const world = await si();
  try {
    const {bodies, decomposition} = createBodiesFromMesh(world, mesh, {as: 'decomposed', position: [0, drop, 0], density, friction: 0.6});
    const mass = bodies.reduce((sum, body) => sum + world.getState(body).mass, 0);
    const corners = () => bodies.flatMap((body, i) => {
      const {position: p, rotation: q} = world.getState(body), points = decomposition.hulls[i].points, out = [];
      for (let k = 0; k < points.length; k += 3) {
        const [x, y, z] = [points[k], points[k + 1], points[k + 2]], [qx, qy, qz, qw] = q;
        const tx = 2 * (qy * z - qz * y), ty = 2 * (qz * x - qx * z), tz = 2 * (qx * y - qy * x);
        out.push([p[0] + x + qw * tx + qy * tz - qz * ty, p[1] + y + qw * ty + qz * tx - qx * tz, p[2] + z + qw * tz + qx * ty - qy * tx]);
      }
      return out;
    });
    run(world, 3);
    const rest = corners();
    return {hulls: split.hulls.length, volumeError: Math.abs(split.volumeError), volume: meshVolume(mesh), mass, top: Math.max(...rest.map(p => p[1]))};
  } finally { world.dispose(); }
});

const importedMass = () => memo('geometry/imported-mass', async () => {
  const {parseGLB, parseOBJ, meshVolume, createBodiesFromMesh} = await geometry();
  const world = await si();
  try {
    const mesh = parseGLB(glbOf(modelMesh(boxModel([-0.2, -0.3, -0.4], [0.2, 0.3, 0.4]))))[0];
    const {bodies} = createBodiesFromMesh(world, mesh, {as: 'hull', position: [2, 0.3, 0], density: 2700});
    const ball = parseOBJ(objText(sphereModel(0.5, 16)))[0];
    const {bodies: [round]} = createBodiesFromMesh(world, ball, {as: 'hull', maxPoints: 64, position: [25, 5, 0], density: 1000});
    return {cube: world.getState(bodies[0]).mass, sphere: world.getState(round).mass, sphereExpected: 1000 * meshVolume(ball)};
  } finally { world.dispose(); }
});

const ramp = () => memo('geometry/ramp', async () => {
  const {parseOBJ, meshVolume, createBodiesFromMesh, toHeightfieldShape} = await geometry();
  const world = await si({ground: false});
  try {
    const theta = 0.3, length = 40, half = 4, c = Math.cos(theta), s = Math.sin(theta), r = 0.25, time = 2;
    const [imported] = parseOBJ(objText(prismModel([[0, 0], [0, -length * s], [length * c, -length * s]], -half, half), {name: 'ramp'}));
    createBodiesFromMesh(world, imported, {as: 'mesh', friction: 0});
    const slider = world.createBody({shape: {kind: 'sphere', radius: r}, position: [c + r * s, -s + r * c, 0], friction: 0});
    run(world, time);
    const speed = Math.hypot(...world.getState(slider).linearVelocity);
    const terrain = toHeightfieldShape(imported, {countX: 81, countZ: 9});
    world.createBody({shape: terrain, position: [terrain.origin[0], terrain.origin[1], terrain.origin[2] + 200]});
    return {volume: meshVolume(imported), speed, height: world.raycast([12.3, 50, 200], [0, -100, 0]).point[1]};
  } finally { world.dispose(); }
});

export default defineCases('geometry', FILE, [
  ...[['obj', 'OBJ'], ['ascii-stl', 'ASCII STL'], ['binary-stl', 'binary STL'], ['glb', 'GLB']].map(([format, label]) => (
    {id: `geometry.cube-volume.${format}`, title: `Unit cube read from ${label}: volume`, quantity: `signed volume of the parsed, welded cube mesh (${label})`, unit: 'm^3', test: T.cube,
      reference: {formula: 'V = a^3', value: 1}, tolerance: absolute(1e-12), note: 'The corners are 0 and 1, exact in float32.', measure: cubeVolume(format)})),
  {id: 'geometry.tetrahedron.volume', title: 'Tetrahedron: volume', quantity: 'volume of a right tetrahedron with legs 1.5, 2 and 3 m', unit: 'm^3', test: T.tetra,
    reference: {formula: 'V = a b c / 6', value: 1.5}, tolerance: absolute(1e-12), measure: async () => (await tetra()).volume},
  {id: 'geometry.tetrahedron.centroid', title: 'Tetrahedron: centroid', quantity: 'largest component error of the centre of mass against (a, b, c) / 4', unit: 'm', test: T.tetra,
    reference: {formula: '|c - (a, b, c) / 4| = 0', value: 0}, tolerance: absolute(1e-12), measure: async () => (await tetra()).centroidError},
  {id: 'geometry.tetrahedron.scaled-volume', title: 'Tetrahedron: volume after scale (2, 3, 4), a turn and a move', quantity: 'volume of the transformed mesh', unit: 'm^3', test: T.tetra,
    reference: {formula: 'V = 24 a b c / 6', value: 36}, tolerance: relative(1e-6), note: 'Vertices are float32.', measure: async () => (await tetra()).scaled},
  {id: 'geometry.sphere.volume', title: 'UV sphere at 64 rings: volume', quantity: 'volume of a 64-ring sphere mesh of radius 0.75 m read from OBJ', unit: 'm^3', test: T.sphere,
    reference: {formula: 'V = (4/3) pi r^3', value: SPHERE_V}, tolerance: relative(2e-3), note: 'An inscribed polyhedron is smaller than the sphere; the error is the faceting.',
    measure: () => sphereVolume(64)},
  {id: 'geometry.sphere.order', title: 'UV sphere: observed order of the volume error', quantity: 'convergence order of the volume error from 32 to 64 rings', unit: '1', test: T.sphere,
    reference: {formula: 'log2(e_32 / e_64) = 2', value: 2}, tolerance: absolute(0.07), note: 'The test accepts an error ratio of 3.8 to 4.2 per doubling.',
    measure: async () => order(SPHERE_V - await sphereVolume(32), SPHERE_V - await sphereVolume(64))},
  {id: 'geometry.hull.cube', title: 'Convex hull of a cube with interior points', quantity: 'volume of the hull of 8 corners plus 5 points inside and on faces', unit: 'm^3', test: T.hull,
    reference: {formula: 'V = a^3', value: 1}, tolerance: absolute(1e-12), measure: async () => (await hullCases()).cube},
  {id: 'geometry.hull.prism', title: 'Convex hull of a 32-sided prism', quantity: 'volume of the 64-point hull of a unit-radius prism of height 2', unit: 'm^3', test: T.hull,
    reference: {formula: 'V = n sin(2 pi / n) r^2 h / 2', value: 32 * Math.sin(2 * Math.PI / 32)}, tolerance: relative(1e-6), measure: async () => (await hullCases()).prism},
  {id: 'geometry.hull.convex-mesh', title: 'The hull of a convex mesh is the mesh', quantity: 'hull volume of a 1,986-vertex sphere mesh', unit: 'm^3', test: T.hull,
    reference: {formula: 'V_hull = V_mesh', value: null}, tolerance: relative(1e-7),
    measure: async () => { const r = await hullCases(); return {value: r.sphereHull, reference: r.sphereMesh}; }},
  {id: 'geometry.decomposition.l-volume', title: 'Convex decomposition of an L: volume error', quantity: 'volume error of the two hulls that an L of three unit cubes splits into', unit: '1', test: T.decompose,
    reference: {formula: '|V_hulls / V_mesh - 1| = 0', value: 0}, tolerance: absolute(1e-9), note: 'Solids with flat inner faces split exactly; curved concavities are only approached (see the limits).',
    measure: async () => (await lShape()).volumeError},
  {id: 'geometry.decomposition.l-mass', title: 'Welded hulls of an L: total mass', quantity: 'summed mass of the hull bodies made from a 0.375 m^3 L of density 600 kg/m^3', unit: 'kg', test: T.welded,
    reference: {formula: 'm = rho V', value: 600 * 3 / 8}, tolerance: relative(1e-5), measure: async () => (await lShape()).mass},
  {id: 'geometry.decomposition.l-rest', title: 'Welded hulls of an L: stands 1 m tall at rest', quantity: 'height of the highest corner after the set is dropped 0.2 m and settles', unit: 'm', test: T.welded,
    reference: {formula: 'y_top = 1', value: 1}, tolerance: absolute(0.006), note: 'Box3D contact slop (5 mm) plus 1 mm.', measure: async () => (await lShape()).top},
  {id: 'geometry.import.cube-mass', title: 'Imported cube as a hull body: mass', quantity: 'mass of a 0.4 x 0.6 x 0.8 m cube read from GLB, density 2700 kg/m^3', unit: 'kg', test: T.mass,
    reference: {formula: 'm = rho V', value: 2700 * 0.192}, tolerance: relative(1e-5), measure: async () => (await importedMass()).cube},
  {id: 'geometry.import.sphere-mass', title: 'Imported sphere mesh as a hull body: mass', quantity: 'mass of a 482-vertex sphere mesh made a 44-point hull body, density 1000 kg/m^3', unit: 'kg', test: T.mass,
    reference: {formula: 'm = rho V_mesh (not the smaller hull volume)', value: null}, tolerance: relative(1e-5),
    measure: async () => { const r = await importedMass(); return {value: r.sphere, reference: r.sphereExpected}; }},
  {id: 'geometry.import.ramp-volume', title: 'Imported wedge: volume', quantity: 'volume of a closed wedge mesh read from OBJ', unit: 'm^3', test: T.ramp,
    reference: {formula: 'V = base x height x width / 2', value: 0.5 * 40 * Math.cos(0.3) * 40 * Math.sin(0.3) * 8}, tolerance: relative(1e-6), measure: async () => (await ramp()).volume},
  {id: 'geometry.import.ramp-slide', title: 'Imported ramp: frictionless sliding', quantity: 'speed of a sphere after 2 s on the imported 0.3 rad ramp', unit: 'm/s', test: T.ramp,
    reference: {formula: 'v = g sin(theta) t', value: G * Math.sin(0.3) * 2}, tolerance: relative(1e-3), measure: async () => (await ramp()).speed},
  {id: 'geometry.import.ramp-terrain', title: 'Imported ramp sampled as a height field', quantity: 'ray hit height at x = 12.3 m on the terrain sampled from the wedge', unit: 'm', test: T.ramp,
    reference: {formula: 'y = -x tan(theta)', value: -12.3 * Math.tan(0.3)}, tolerance: absolute(1e-3), note: 'Heights are quantised to 16 bits over the 11.8 m range: about 0.2 mm.',
    measure: async () => (await ramp()).height},
]);
